Q: How to set an item selected in extjs tree panel by default? A: <p>Please refer this code. This will work</p>

<pre><code>Ext.each(Nodes, function(item, index, allNodes)
{
    var rec = TreePanelObj.getView().getRecord(item);
    if() //any condition 
    {
        TreePanelObj.getSelectionModel().select(index);
    }
});
</code></pre>
